const item = $input.item.json;
const rawEpics = item.epics || [];

const treeData = (Array.isArray(rawEpics) ? rawEpics : []).map((epic, ei) => {
  const epicId = `epic-${ei}`;
  const rawStories = epic.stories || epic.user_stories || epic.userStories || [];

  const stories = (Array.isArray(rawStories) ? rawStories : []).map((story, si) => {
    const storyId = `${epicId}-story-${si}`;
    const rawTasks = story.tasks || story.subtasks || [];

    const tasks = (Array.isArray(rawTasks) ? rawTasks : []).map((task, ti) => {
      const taskId = `${storyId}-task-${ti}`;
      const title = typeof task === 'string' ? task.trim() : String(task.title || task.name || `Task #${ti + 1}`).trim();
      const description = typeof task === 'object' ? String(task.description || task.desc || '').trim() : '';

      return {
        id: taskId,
        parentId: storyId,
        level: 3,
        type: 'Task',
        title: title,
        description: description,
        assigneeId: typeof task === 'object' ? task.assigneeId || null : null,
        assigneeName: typeof task === 'object' ? task.assigneeName || '' : '',
        assigneeAvatar: typeof task === 'object' ? task.assigneeAvatar || '' : ''
      };
    });

    const sTitle = String(story.title || story.name || story.user_story || `User Story #${si + 1}`).trim();
    const sDesc = String(story.description || story.desc || '').trim();

    return {
      id: storyId,
      parentId: epicId,
      level: 2,
      type: 'Story',
      title: sTitle,
      description: sDesc,
      assigneeId: story.assigneeId || null,
      assigneeName: story.assigneeName || '',
      assigneeAvatar: story.assigneeAvatar || '',
      tasks: tasks
    };
  });

  const eTitle = String(epic.title || epic.name || epic.epic_name || `Epic #${ei + 1}`).trim();
  const eDesc = String(epic.description || epic.details || epic.desc || '').trim();

  return {
    id: epicId,
    parentId: null,
    level: 1,
    type: 'Epic',
    title: eTitle,
    description: eDesc,
    stories: stories
  };
});

return {
  json: {
    ...item,
    treeData: treeData
  }
};

const item = $input.item.json;
const tree = item.treeData || [];

let totalEpics = tree.length;
let totalStories = 0;
let totalTasks = 0;
let storiesWithoutTasks = 0;
let epicsWithoutStories = 0;
const warnings = [];

tree.forEach((epic) => {
  const stories = epic.stories || [];
  if (stories.length === 0) {
    epicsWithoutStories++;
    warnings.push(`Epic "${epic.title}" (ID: ${epic.id}) không chứa bất kỳ User Story nào.`);
  }
  totalStories += stories.length;

  stories.forEach((story) => {
    const tasks = story.tasks || [];
    if (tasks.length === 0) {
      storiesWithoutTasks++;
      warnings.push(`Story "${story.title}" (ID: ${story.id}) không có Sub-task kỹ thuật nào.`);
    }
    totalTasks += tasks.length;
  });
});

const hasFatalError = totalEpics > 0 && totalStories === 0;

let penalty = (epicsWithoutStories * 25) + (storiesWithoutTasks * 10);
let healthScore = Math.max(100 - penalty, 0);
if (hasFatalError) healthScore = 0;

return {
  json: {
    ...item,
    hasFatalError: hasFatalError,
    healthScore: healthScore,
    warnings: warnings,
    auditStats: {
      epicsWithoutStories: epicsWithoutStories,
      storiesWithoutTasks: storiesWithoutTasks
    }
  }
};

const item = $input.item.json;
const tree = item.treeData || [];

let totalStories = 0;
let totalTasks = 0;
let maxDepth = tree.length > 0 ? 1 : 0;

tree.forEach((epic) => {
  const stories = epic.stories || [];
  if (stories.length > 0 && maxDepth < 2) maxDepth = 2;
  totalStories += stories.length;

  stories.forEach((story) => {
    const tasks = story.tasks || [];
    if (tasks.length > 0) maxDepth = 3;
    totalTasks += tasks.length;
  });
});

const avgTasksPerStory = totalStories > 0 ? parseFloat((totalTasks / totalStories).toFixed(1)) : 0;
const startMs = item.timestamp ? new Date(item.timestamp).getTime() : Date.now();
const transformationDurationMs = Math.max(Date.now() - startMs, 5);

const kpiMetrics = {
  totalEpics: tree.length,
  totalStories: totalStories,
  totalTasks: totalTasks,
  totalNodes: tree.length + totalStories + totalTasks,
  treeDepth: maxDepth,
  avgTasksPerStory: avgTasksPerStory,
  transformationDurationMs: transformationDurationMs
};

return {
  json: {
    ...item,
    kpiMetrics: kpiMetrics
  }
};

const item = $input.item.json;
const tree = item.treeData || [];

const expandedNodesMap = {};
const uniqueAssignees = new Set();

tree.forEach((epic) => {
  expandedNodesMap[epic.id] = true;
  (epic.stories || []).forEach((story) => {
    expandedNodesMap[story.id] = true;
    if (story.assigneeName) uniqueAssignees.add(story.assigneeName);
    (story.tasks || []).forEach((task) => {
      if (task.assigneeName) uniqueAssignees.add(task.assigneeName);
    });
  });
});

const uiTheme = {
  levelColors: {
    1: { name: 'Epic', color: '#7c3aed', badge: 'bg-purple-100 text-purple-700' },
    2: { name: 'User Story', color: '#2563eb', badge: 'bg-blue-100 text-blue-700' },
    3: { name: 'Sub-task', color: '#16a34a', badge: 'bg-green-100 text-green-700' }
  },
  totalAssigneesCount: uniqueAssignees.size
};

return {
  json: {
    ...item,
    uiConfig: {
      expandedNodesMap: expandedNodesMap,
      theme: uiTheme
    }
  }
};
